package com.legacyai.file;
import com.legacyai.exception.InvalidFileException; import java.io.*; import java.nio.file.*; import java.util.*; import java.util.zip.*;
public class ZipProcessor { private static final Set<String> IGNORED=Set.of(".git","node_modules","target","build","dist",".idea",".vscode"); public List<Path> extractSafely(Path zip,Path directory)throws IOException{List<Path> result=new ArrayList<>();Path root=directory.toAbsolutePath().normalize();try(ZipInputStream in=new ZipInputStream(Files.newInputStream(zip))){for(ZipEntry entry;(entry=in.getNextEntry())!=null;){Path out=root.resolve(entry.getName()).normalize();if(!out.startsWith(root))throw new InvalidFileException("Caminho ZIP inválido");if(entry.isDirectory()||ignored(root.relativize(out))){continue;}Files.createDirectories(out.getParent());Files.copy(in,out,StandardCopyOption.REPLACE_EXISTING);if(!binary(out))result.add(out);else Files.deleteIfExists(out);}}return result;} private boolean ignored(Path path){for(Path part:path){if(IGNORED.contains(part.toString()))return true;}return false;} private boolean binary(Path p)throws IOException{try(InputStream in=Files.newInputStream(p)){byte[] b=in.readNBytes(4096);for(byte x:b)if(x==0)return true;return false;}}}
